'use client'

import { useState } from 'react'
import { TrendingUp, TrendingDown, Minus, AlertCircle } from 'lucide-react'
import { cn } from '@/lib/utils'
import { HygieneModal } from './HygieneModal'

interface MarketingKPIData {
  open_rate_30d: number
  open_rate_delta: number
  bookings_driven_30d: number
  revenue_attributed_cents: number
  bounces: number
  unsubs: number
  complaints: number
}

interface MarketingKPIsProps {
  data: MarketingKPIData
  studioId: string
}

function DeltaLine({ delta }: { delta: number }) {
  if (delta === 0) {
    return (
      <p className="flex items-center gap-1 text-xs text-[color:var(--color-stone)] tabular-nums">
        <Minus className="h-3 w-3" aria-hidden="true" />
        No change vs prior
      </p>
    )
  }
  const isPositive = delta > 0
  return (
    <p
      className={cn(
        'flex items-center gap-1 text-xs tabular-nums',
        isPositive ? 'text-[color:var(--color-onyx)]' : 'text-[color:var(--color-stone)]',
      )}
    >
      {isPositive ? (
        <TrendingUp className="h-3 w-3" aria-hidden="true" />
      ) : (
        <TrendingDown className="h-3 w-3" aria-hidden="true" />
      )}
      {isPositive ? '+' : ''}
      {delta.toFixed(1)}% vs prior 30d
    </p>
  )
}

export function MarketingKPIs({ data, studioId }: MarketingKPIsProps) {
  const [hygieneOpen, setHygieneOpen] = useState(false)

  const totalHygiene = data.bounces + data.unsubs + data.complaints
  const hasHygieneIssues = totalHygiene > 0

  const revenueFormatted = (data.revenue_attributed_cents / 100).toLocaleString('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  })

  return (
    <>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        {/* KPI 1 — Open Rate (hero: 2px Rust left border) */}
        <div
          className="rounded-lg border border-[color:var(--color-border)] bg-white shadow-card p-5 border-l-2 border-l-[color:var(--color-rust)]"
          aria-label={`Open rate 30 days: ${data.open_rate_30d.toFixed(1)} percent`}
        >
          <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-3">
            OPEN RATE · 30D
          </p>
          <p className="text-[52px] font-extrabold leading-none tabular-nums text-[color:var(--color-onyx)] mb-2">
            {data.open_rate_30d.toFixed(1)}%
          </p>
          <DeltaLine delta={data.open_rate_delta} />
        </div>

        {/* KPI 2 — Bookings Driven */}
        <div
          className="rounded-lg border border-[color:var(--color-border)] bg-white shadow-card p-5"
          aria-label={`Bookings driven in 30 days: ${data.bookings_driven_30d}`}
        >
          <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-3">
            BOOKINGS DRIVEN · 30D
          </p>
          <p className="text-[52px] font-extrabold leading-none tabular-nums text-[color:var(--color-onyx)] mb-2">
            {data.bookings_driven_30d.toLocaleString()}
          </p>
          <p className="text-xs text-[color:var(--color-stone)] tabular-nums">
            {revenueFormatted} attributed
          </p>
        </div>

        {/* KPI 3 — Hygiene */}
        <div
          className={cn(
            'rounded-lg border border-[color:var(--color-border)] bg-white shadow-card p-5',
            hasHygieneIssues && 'bg-[color:var(--color-rust)]/5 border-[color:var(--color-rust)]/20',
          )}
          aria-label={`Hygiene: ${data.bounces} bounces, ${data.unsubs} unsubscribes, ${data.complaints} complaints`}
        >
          <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-3">
            HYGIENE
          </p>
          <div className="space-y-1 mb-2">
            <div className="flex items-center justify-between">
              <span className="text-xs text-[color:var(--color-stone)]">Bounces</span>
              <span
                className={cn(
                  'text-sm font-semibold tabular-nums',
                  data.bounces > 0
                    ? 'text-[color:var(--color-rust)]'
                    : 'text-[color:var(--color-onyx)]',
                )}
              >
                {data.bounces.toLocaleString()}
              </span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-xs text-[color:var(--color-stone)]">Unsubscribes</span>
              <span className="text-sm font-semibold tabular-nums text-[color:var(--color-onyx)]">
                {data.unsubs.toLocaleString()}
              </span>
            </div>
          </div>
          {hasHygieneIssues ? (
            <button
              type="button"
              onClick={() => setHygieneOpen(true)}
              className="flex items-center gap-1 text-xs text-[color:var(--color-rust)] hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--color-rust)]/50 rounded"
              aria-label={`Review and remove ${totalHygiene} hygiene issues`}
            >
              <AlertCircle className="h-3 w-3" aria-hidden="true" />
              Review &amp; remove →
            </button>
          ) : (
            <p className="text-xs text-[color:var(--color-stone)]">List is clean.</p>
          )}
        </div>
      </div>

      <HygieneModal
        open={hygieneOpen}
        onOpenChange={setHygieneOpen}
        studioId={studioId}
      />
    </>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'

interface HygieneEntry {
  email: string
  reason: string
  created_at: string
}

interface HygieneData {
  bounces: HygieneEntry[]
  unsubs: HygieneEntry[]
  complaints: HygieneEntry[]
}

interface HygieneModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  studioId: string
}

function EntryRow({ entry, selected, onToggle }: {
  entry: HygieneEntry
  selected: boolean
  onToggle: () => void
}) {
  const date = new Date(entry.created_at).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  })
  return (
    <label className="flex items-start gap-3 rounded px-2 py-2 hover:bg-[color:var(--color-bone)] cursor-pointer">
      <input
        type="checkbox"
        checked={selected}
        onChange={onToggle}
        className="mt-0.5 accent-[color:var(--color-onyx)]"
        aria-label={`Select ${entry.email}`}
      />
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-[color:var(--color-onyx)] truncate">{entry.email}</p>
        <p className="text-xs text-[color:var(--color-stone)]">{entry.reason} · {date}</p>
      </div>
    </label>
  )
}

function TabPane({
  entries,
  selected,
  onToggle,
  onToggleAll,
}: {
  entries: HygieneEntry[]
  selected: Set<string>
  onToggle: (email: string) => void
  onToggleAll: () => void
}) {
  if (entries.length === 0) {
    return (
      <p className="py-8 text-center font-serif italic text-base text-[color:var(--color-stone)]">
        Nothing here.
      </p>
    )
  }
  const allSelected = entries.every((e) => selected.has(e.email))
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-2 px-2 pb-1 border-b border-[color:var(--color-border)]">
        <input
          type="checkbox"
          checked={allSelected}
          onChange={onToggleAll}
          className="accent-[color:var(--color-onyx)]"
          aria-label="Select all"
        />
        <span className="text-xs text-[color:var(--color-stone)]">Select all</span>
      </div>
      {entries.map((entry) => (
        <EntryRow
          key={entry.email}
          entry={entry}
          selected={selected.has(entry.email)}
          onToggle={() => onToggle(entry.email)}
        />
      ))}
    </div>
  )
}

export function HygieneModal({ open, onOpenChange }: HygieneModalProps) {
  const [data, setData] = useState<HygieneData | null>(null)
  const [loading, setLoading] = useState(false)
  const [suppressing, setSuppressing] = useState(false)
  const [selected, setSelected] = useState<Set<string>>(new Set())

  const fetchData = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/marketing/hygiene')
      if (!res.ok) throw new Error('Failed to load hygiene data')
      const json = await res.json() as { data: HygieneData }
      setData(json.data)
    } catch {
      toast.error('Could not load hygiene data.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    if (open) {
      setSelected(new Set())
      void fetchData()
    }
  }, [open, fetchData])

  function toggleEmail(email: string) {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(email)) next.delete(email)
      else next.add(email)
      return next
    })
  }

  function toggleAll(entries: HygieneEntry[]) {
    const allSelected = entries.every((e) => selected.has(e.email))
    setSelected((prev) => {
      const next = new Set(prev)
      if (allSelected) {
        for (const e of entries) next.delete(e.email)
      } else {
        for (const e of entries) next.add(e.email)
      }
      return next
    })
  }

  async function handleSuppress() {
    if (selected.size === 0) return
    setSuppressing(true)
    try {
      const res = await fetch('/api/marketing/hygiene/suppress', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ emails: Array.from(selected) }),
      })
      if (!res.ok) throw new Error('Suppress failed')
      const json = await res.json() as { count: number }
      toast.success(`${json.count} email${json.count !== 1 ? 's' : ''} suppressed.`)
      setSelected(new Set())
      void fetchData()
    } catch {
      toast.error('Could not suppress emails. Try again.')
    } finally {
      setSuppressing(false)
    }
  }

  const totals = data
    ? { bounces: data.bounces.length, unsubs: data.unsubs.length, complaints: data.complaints.length }
    : { bounces: 0, unsubs: 0, complaints: 0 }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[640px] bg-[color:var(--color-bone)] shadow-soft-md">
        <DialogHeader>
          <DialogTitle className="text-base font-semibold text-[color:var(--color-onyx)]">
            Audience hygiene
          </DialogTitle>
          <DialogDescription className="text-xs text-[color:var(--color-stone)]">
            Review bounced, unsubscribed, and complaint emails. Suppress to clean your sends.
          </DialogDescription>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-5 w-5 animate-spin text-[color:var(--color-stone)]" aria-label="Loading" />
          </div>
        ) : (
          <Tabs defaultValue="bounces">
            <TabsList variant="line" className="mb-4 w-full justify-start">
              <TabsTrigger value="bounces">
                Bounces
                {totals.bounces > 0 && (
                  <Badge variant="chip-rust" className="ml-1.5 tabular-nums">
                    {totals.bounces}
                  </Badge>
                )}
              </TabsTrigger>
              <TabsTrigger value="unsubs">
                Unsubscribes
                {totals.unsubs > 0 && (
                  <Badge variant="chip-stone" className="ml-1.5 tabular-nums">
                    {totals.unsubs}
                  </Badge>
                )}
              </TabsTrigger>
              <TabsTrigger value="complaints">
                Complaints
                {totals.complaints > 0 && (
                  <Badge variant="chip-stone" className="ml-1.5 tabular-nums">
                    {totals.complaints}
                  </Badge>
                )}
              </TabsTrigger>
            </TabsList>

            <div
              className={cn(
                'max-h-[320px] overflow-y-auto rounded-md border border-[color:var(--color-border)] bg-white p-2',
              )}
            >
              <TabsContent value="bounces">
                <TabPane
                  entries={data?.bounces ?? []}
                  selected={selected}
                  onToggle={toggleEmail}
                  onToggleAll={() => toggleAll(data?.bounces ?? [])}
                />
              </TabsContent>
              <TabsContent value="unsubs">
                <TabPane
                  entries={data?.unsubs ?? []}
                  selected={selected}
                  onToggle={toggleEmail}
                  onToggleAll={() => toggleAll(data?.unsubs ?? [])}
                />
              </TabsContent>
              <TabsContent value="complaints">
                <TabPane
                  entries={data?.complaints ?? []}
                  selected={selected}
                  onToggle={toggleEmail}
                  onToggleAll={() => toggleAll(data?.complaints ?? [])}
                />
              </TabsContent>
            </div>
          </Tabs>
        )}

        <DialogFooter className="border-t-0 bg-transparent p-0 mt-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onOpenChange(false)}
          >
            Close
          </Button>
          <Button
            size="sm"
            disabled={selected.size === 0 || suppressing}
            onClick={handleSuppress}
            className="bg-[color:var(--color-onyx)] text-[color:var(--color-bone)] hover:bg-[color:var(--color-onyx)]/90"
          >
            {suppressing && <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" aria-hidden="true" />}
            Suppress selected ({selected.size})
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { AudienceFilterBuilder } from '@/components/marketing/AudienceFilterBuilder'
import type { AudienceFilter } from '@/lib/marketing/types'

interface CustomSegmentDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  studioId: string
  locationOptions?: Array<{ id: string; name: string }>
}

export function CustomSegmentDialog({
  open,
  onOpenChange,
  studioId,
  locationOptions = [],
}: CustomSegmentDialogProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  const [name, setName] = useState('')
  const [filter, setFilter] = useState<AudienceFilter>({})
  const [saving, setSaving] = useState(false)
  const [savedId, setSavedId] = useState<string | null>(null)

  async function handleSave() {
    if (!name.trim()) {
      toast.error('Segment name is required.')
      return
    }
    setSaving(true)
    try {
      const res = await fetch('/api/marketing/segments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: name.trim(), filter }),
      })
      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Failed to save segment')
      }
      const json = await res.json() as { id: string; name: string }
      toast.success(`Segment "${json.name}" saved.`)
      setSavedId(json.id)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Could not save segment.')
    } finally {
      setSaving(false)
    }
  }

  function handleUseCampaign() {
    if (!savedId) return
    const params = new URLSearchParams(searchParams.toString())
    params.set('campaign', 'new')
    params.set('segment_id', savedId)
    router.push(`${pathname}?${params.toString()}`)
    onOpenChange(false)
  }

  function handleClose() {
    // Reset state on close
    setName('')
    setFilter({})
    setSavedId(null)
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[640px] bg-[color:var(--color-bone)] shadow-soft-md">
        <DialogHeader>
          <DialogTitle className="text-base font-semibold text-[color:var(--color-onyx)]">
            Custom segment
          </DialogTitle>
          <DialogDescription className="text-xs text-[color:var(--color-stone)]">
            Build a filter, name it, and save for reuse — or use it immediately in a new campaign.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 py-1">
          <div className="space-y-1.5">
            <Label htmlFor="segment-name" className="text-xs font-semibold text-[color:var(--color-onyx)]">
              Segment name
            </Label>
            <Input
              id="segment-name"
              placeholder="e.g. Inactive VIPs"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="h-9 text-sm"
              maxLength={80}
            />
          </div>

          <div className="space-y-1.5">
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">
              AUDIENCE FILTER
            </p>
            <AudienceFilterBuilder
              value={filter}
              onChange={setFilter}
              studioId={studioId}
              locationOptions={locationOptions}
            />
          </div>
        </div>

        <DialogFooter className="border-t-0 bg-transparent p-0 mt-2">
          <Button variant="outline" size="sm" onClick={handleClose}>
            Cancel
          </Button>

          {savedId ? (
            <Button
              size="sm"
              onClick={handleUseCampaign}
              className="bg-[color:var(--color-onyx)] text-[color:var(--color-bone)] hover:bg-[color:var(--color-onyx)]/90"
            >
              Use in new campaign →
            </Button>
          ) : (
            <Button
              size="sm"
              disabled={saving || !name.trim()}
              onClick={handleSave}
              className="bg-[color:var(--color-onyx)] text-[color:var(--color-bone)] hover:bg-[color:var(--color-onyx)]/90"
            >
              {saving && <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" aria-hidden="true" />}
              Save segment
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

