/**
 * AudienceTab — Sprint M3 full build.
 *
 * Server Component. Fetches segment counts, recent campaigns (30d),
 * and 30d KPIs directly from Supabase and passes hydrated data down.
 */

import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { SegmentChipsRow } from './SegmentChipsRow'
import { RecentCampaignsList } from './RecentCampaignsList'
import { MarketingKPIs } from './MarketingKPIs'
import type { CampaignStatus, CampaignChannel } from '@/lib/marketing/types'
import type { SupabaseClient } from '@supabase/supabase-js'

interface AudienceTabProps {
  studioId: string
  locationOptions?: Array<{ id: string; name: string }>
}

interface SegmentCounts {
  all: number
  inactive_90d: number
  new_30d: number
  top_spenders: number
  birthday_month: number
  booked_next_14d: number
  unsubscribed: number
}

interface KPIData {
  open_rate_30d: number
  open_rate_prior_30d: number
  bookings_driven_30d: number
  revenue_attributed_cents: number
  bounces: number
  unsubs: number
  complaints: number
}

// RPC helper — casts away the generated types registry until pnpm db:types re-run
async function callKpisRpc(
  supabase: SupabaseClient,
  studioId: string,
): Promise<KPIData> {
  const client = supabase as unknown as {
    rpc: (fn: string, args: Record<string, string>) => Promise<{
      data: KPIData | null
      error: { message: string } | null
    }>
  }
  const { data, error } = await client.rpc('get_marketing_kpis_30d', { p_studio_id: studioId })
  if (error) {
    logger.warn({ err: error, studioId }, 'get_marketing_kpis_30d rpc failed — returning zeros')
  }
  return data ?? {
    open_rate_30d: 0,
    open_rate_prior_30d: 0,
    bookings_driven_30d: 0,
    revenue_attributed_cents: 0,
    bounces: 0,
    unsubs: 0,
    complaints: 0,
  }
}

async function callSegmentCountsRpc(
  supabase: SupabaseClient,
  studioId: string,
): Promise<SegmentCounts> {
  const client = supabase as unknown as {
    rpc: (fn: string, args: Record<string, string>) => Promise<{
      data: SegmentCounts | null
      error: { message: string } | null
    }>
  }
  const { data, error } = await client.rpc('get_marketing_segment_counts', { p_studio_id: studioId })
  if (error) {
    logger.warn({ err: error, studioId }, 'get_marketing_segment_counts rpc failed — returning zeros')
  }
  return data ?? {
    all: 0, inactive_90d: 0, new_30d: 0, top_spenders: 0,
    birthday_month: 0, booked_next_14d: 0, unsubscribed: 0,
  }
}

interface RawRecentCampaign {
  id: string
  name: string
  channel: string
  status: string
  sent_count: number | null
  open_count: number | null
  sent_at: string | null
  scheduled_at: string | null
}

export async function AudienceTab({ studioId, locationOptions = [] }: AudienceTabProps) {
  const supabase = await createClient()

  const thirtyDaysAgo = new Date()
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30)
  const thirtyDaysAgoISO = thirtyDaysAgo.toISOString()

  // Parallel server-side fetches
  const [kpiData, recentCampaignsResult] = await Promise.all([
    callKpisRpc(supabase, studioId),
    supabase
      .from('marketing_campaigns')
      .select('id, name, channel, status, sent_count, open_count, sent_at, scheduled_at')
      .eq('studio_id', studioId)
      .gte('sent_at', thirtyDaysAgoISO)
      .in('status', ['sent', 'sending'])
      .order('sent_at', { ascending: false })
      .limit(5),
  ])

  // segment counts are fetched client-side by SegmentPresetChips via /api/marketing/segments
  // — that way the chips show spinner until counts arrive without blocking SSR

  const rawCampaigns = (recentCampaignsResult.data ?? []) as unknown as RawRecentCampaign[]

  const recentCampaigns = rawCampaigns.map((c) => {
    const sentCount = c.sent_count ?? 0
    const openRate =
      sentCount > 0 && c.open_count !== null
        ? parseFloat(((c.open_count / sentCount) * 100).toFixed(1))
        : null
    return {
      id: c.id,
      name: c.name,
      channel: c.channel as CampaignChannel,
      audience_size: sentCount || null,
      sent_at: c.sent_at ?? c.scheduled_at,
      recipients_count: sentCount,
      open_rate: openRate,
      bookings_driven: 0, // attribution requires marketing_sends — show 0 until M6 worker wires it
      status: c.status as CampaignStatus,
    }
  })

  const kpiCardData = {
    open_rate_30d: kpiData.open_rate_30d,
    open_rate_delta: kpiData.open_rate_30d - kpiData.open_rate_prior_30d,
    bookings_driven_30d: kpiData.bookings_driven_30d,
    revenue_attributed_cents: kpiData.revenue_attributed_cents,
    bounces: kpiData.bounces,
    unsubs: kpiData.unsubs,
    complaints: kpiData.complaints,
  }

  return (
    <div className="space-y-6 py-2">
      {/* Segment chips + custom segment */}
      <SegmentChipsRow studioId={studioId} locationOptions={locationOptions} />

      {/* KPI strip */}
      <MarketingKPIs data={kpiCardData} studioId={studioId} />

      {/* Recent campaigns */}
      <RecentCampaignsList campaigns={recentCampaigns} />
    </div>
  )
}

import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
