    }>
  }
  const result = await client.rpc('get_marketing_segment_counts', { p_studio_id: studioId })
  return {
    data: result.data,
    error: result.error ? new Error(result.error.message) : null,
  }
}

const EMPTY_COUNTS: SegmentCounts = {
  all: 0,
  inactive_90d: 0,
  new_30d: 0,
  top_spenders: 0,
  birthday_month: 0,
  booked_next_14d: 0,
  unsubscribed: 0,
}

// ─────────────────────────────────────────────────────────────────────────────
// GET — segment preset counts
// ─────────────────────────────────────────────────────────────────────────────

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const { data, error } = await callSegmentCountsRpc(supabase, authUser.studioId)

    if (error) {
      logger.warn({ err: error, studioId: authUser.studioId }, 'segment counts rpc failed — returning empty counts')
      return NextResponse.json({ data: EMPTY_COUNTS })
    }

    return NextResponse.json({ data: data ?? EMPTY_COUNTS })
  } catch (err) {
    logger.error({ err }, 'segment counts unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST — create a saved audience segment
// ─────────────────────────────────────────────────────────────────────────────

const CreateSegmentSchema = z.object({
  name: z.string().min(1, 'Name is required').max(120),
  filter: z.record(z.unknown()),
})

export async function POST(request: Request) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateSegmentSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Invalid input' }, { status: 422 })
  }

  const { name, filter } = parsed.data

  try {
    const supabase = await createClient()

    // audience_segments table was created in the M6 migration.
    // The table columns: id, studio_id, name, filter (JSONB), created_by, created_at, updated_at
    const { data, error } = await supabase
      .from('audience_segments')
      .insert({
        studio_id: authUser.studioId,
        name,
        filter,
        created_by: authUser.user.id,
      })
      .select('id, name')
      .single()

    if (error) {
      // If the table doesn't exist yet (pre-M6 migration), return a graceful error
      logger.warn({ err: error, studioId: authUser.studioId }, 'audience_segments insert failed')
      return NextResponse.json({ error: 'Could not save segment. Database migration may be pending.' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'audience_segment.created',
      { type: 'audience_segment', id: data.id },
      { name, filter },
      authUser.studioId,
    )

    return NextResponse.json({ id: data.id, name: data.name }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'audience segment create unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

interface RouteContext {
  params: Promise<{ id: string }>
}

// ─────────────────────────────────────────────────────────────────────────────
// GET — fetch a single saved segment
// ─────────────────────────────────────────────────────────────────────────────

export async function GET(_request: Request, context: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await context.params

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('audience_segments')
      .select('id, name, filter, created_at')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (error || !data) {
      return NextResponse.json({ error: 'Segment not found' }, { status: 404 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err, id }, 'segment fetch unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// DELETE — remove a saved segment
// ─────────────────────────────────────────────────────────────────────────────

export async function DELETE(_request: Request, context: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await context.params

  try {
    const supabase = await createClient()
    const { error } = await supabase
      .from('audience_segments')
      .delete()
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      logger.warn({ err: error, id }, 'segment delete failed')
      return NextResponse.json({ error: 'Could not delete segment' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'audience_segment.deleted',
      { type: 'audience_segment', id },
      null,
      authUser.studioId,
    )

    return NextResponse.json({ deleted: true })
  } catch (err) {
    logger.error({ err, id }, 'segment delete unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()

    // email_suppression_list columns: studio_id, email, reason, created_at
    const { data, error } = await supabase
      .from('email_suppression_list')
      .select('email, reason, created_at')
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })
      .limit(100)

    if (error) {
      logger.warn({ err: error, studioId: authUser.studioId }, 'hygiene list fetch failed')
      // Table may not exist yet (pre-M6 migration) — return empty lists gracefully
      return NextResponse.json({
        data: { bounces: [], unsubs: [], complaints: [] },
      })
    }

    type Row = { email: string; reason: string; created_at: string }
    const rows = (data ?? []) as Row[]

    const bounces = rows.filter((r) => r.reason === 'bounce')
    const unsubs = rows.filter((r) => r.reason === 'unsubscribe')
    const complaints = rows.filter((r) => r.reason === 'complaint')

    return NextResponse.json({ data: { bounces, unsubs, complaints } })
  } catch (err) {
    logger.error({ err }, 'hygiene list unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

