    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = SuppressSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Invalid input' }, { status: 422 })
  }

  const { emails } = parsed.data

  try {
    const supabase = await createClient()
    const { count, error } = await callBulkSuppressRpc(supabase, emails, 'manual')

    if (error) {
      // Fallback: table may not exist yet (pre-M6 migration)
      logger.warn({ err: error, studioId: authUser.studioId }, 'bulk_suppress_emails rpc failed')
      return NextResponse.json({ error: 'Could not suppress emails. Database migration may be pending.' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'email_suppression.bulk_manual',
      null,
      { emails, count, reason: 'manual' },
      authUser.studioId,
    )

    return NextResponse.json({ count })
  } catch (err) {
    logger.error({ err }, 'suppress emails unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

