import { useEffect, useState } from 'react'
import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { CampaignEditor } from './CampaignEditor'
import type { ComponentProps } from 'react'
import type { AudienceFilter } from '@/lib/marketing/types'
import type { SegmentSlug } from './SegmentPresetChips'

type EditorOptionalProps = Pick<ComponentProps<typeof CampaignEditor>, 'studioTimezone' | 'studioName' | 'campaignId'>

interface CampaignDrawerProps {
  studioId: string
  studioTimezone?: string
  studioName?: string
  locationOptions?: Array<{ id: string; name: string }>
}

// Segment slug → default audience filter preset (matches segmentToFilter in CampaignEditor)
function slugToFilter(slug: SegmentSlug): AudienceFilter {
  switch (slug) {
    case 'inactive_90d':     return { last_visit_days: 90 }
    case 'new_30d':          return { last_visit_days: 30 }
    case 'top_spenders':     return { min_spent_cents: 50000 }
    default:                 return {}
  }
}

export function CampaignDrawer({
  studioId,
  studioTimezone,
  studioName,
  locationOptions = [],
}: CampaignDrawerProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const campaignParam = searchParams.get('campaign')

  // segment slug from ?segment=inactive_90d
  const segmentSlug = searchParams.get('segment') as SegmentSlug | null
  // saved segment id from ?segment_id=<uuid>
  const segmentId = searchParams.get('segment_id')

  const isOpen = campaignParam === 'new' || (!!campaignParam && campaignParam !== 'new')
  const isEdit = isOpen && campaignParam !== 'new'

  // Resolved audience filter from segment_id lookup (async)
  const [resolvedFilter, setResolvedFilter] = useState<AudienceFilter | null>(null)
  const [resolvedSegmentSlug, setResolvedSegmentSlug] = useState<SegmentSlug | null>(null)

  // When the drawer opens, resolve the prefill source
  useEffect(() => {
    if (!isOpen) {
      setResolvedFilter(null)
      setResolvedSegmentSlug(null)
      return
    }

    if (segmentId) {
      // Fetch the saved segment filter by id
      fetch(`/api/marketing/segments/${segmentId}`)
        .then((r) => r.ok ? r.json() : null)
        .then((json: unknown) => {
          if (
            json &&
            typeof json === 'object' &&
            'data' in json &&
            json.data &&
            typeof json.data === 'object' &&
            'filter' in json.data
          ) {
            setResolvedFilter((json.data as { filter: AudienceFilter }).filter)
          }
        })
        .catch(() => { /* non-blocking */ })
      return
    }

    if (segmentSlug) {
      setResolvedSegmentSlug(segmentSlug)
      setResolvedFilter(slugToFilter(segmentSlug))
    }
  }, [isOpen, segmentId, segmentSlug])

  function closeDrawer() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('campaign')
    params.delete('segment')
    params.delete('segment_id')
    const qs = params.toString()
    router.replace(qs ? `${pathname}?${qs}` : pathname)
  }

  function handleSaved(id: string) {
    const params = new URLSearchParams(searchParams.toString())
    params.set('campaign', id)
    params.delete('segment')
    params.delete('segment_id')
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  // Build optional props without assigning undefined — exactOptionalPropertyTypes safe
  const optionalProps: EditorOptionalProps = {}
  if (isEdit && campaignParam) optionalProps.campaignId = campaignParam
  if (studioTimezone) optionalProps.studioTimezone = studioTimezone
  if (studioName) optionalProps.studioName = studioName

  // Compute defaultValues for prefill
  const editorDefaultValues =
    resolvedFilter || resolvedSegmentSlug
      ? { audience_filter: resolvedFilter ?? {} }
      : undefined

  return (
    <Sheet open={isOpen} onOpenChange={(open) => { if (!open) closeDrawer() }}>
      <SheetContent
        side="right"
        className="w-full sm:max-w-[48rem] overflow-y-auto bg-[color:var(--color-bone)] p-0 shadow-soft-md"
        aria-describedby="campaign-drawer-desc"
      >
        <div className="sticky top-0 z-10 border-b bg-[color:var(--color-bone)] px-6 py-4">
          <SheetHeader>
            <SheetTitle className="text-base font-semibold text-[color:var(--color-onyx)]">
              {isEdit ? 'Edit campaign' : 'New campaign'}
            </SheetTitle>
            <SheetDescription id="campaign-drawer-desc" className="text-xs text-[color:var(--color-stone)]">
              Fill out all sections below, then confirm to send or schedule.
            </SheetDescription>
          </SheetHeader>
        </div>

        <div className="px-6 pt-4 pb-32 relative">
          <CampaignEditor
            key={`${campaignParam ?? 'new'}-${segmentSlug ?? ''}-${segmentId ?? ''}`}
            {...optionalProps}
            studioId={studioId}
            locationOptions={locationOptions}
            mode={isEdit ? 'edit' : 'create'}
            defaultValues={editorDefaultValues}
            defaultSegmentSlug={resolvedSegmentSlug}
            onSaved={handleSaved}
            onCancel={closeDrawer}
          />
        </div>
      </SheetContent>
    </Sheet>
  )
}

